                    <label>출장 복귀일</label>
                    <input type="date" name="end_date" required>
                </div>
            </div>

            <div class="grid-2 form-group">
                <div>
                    <label>출발지 (Origin)</label>
                    <input type="text" name="origin" placeholder="예: 서울역" required>
